import{_ as i,W as o,s as p,u as r,ah as u,I as l,w as e,Z as s,A as a}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const b=JSON.parse('{"title":"Linux 上的 NVMe | LCTT x X-CMD","titleTemplate":false,"description":"Linux 上的 NVMe | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"Linux 上的 NVMe | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 上的 NVMe | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190529 NVMe on Linux","title":"Linux 上的 NVMe","tag":"201906"},"relativePath":"201906/20190529 NVMe on Linux.md","filePath":"[post].md"}'),d={name:"201906/20190529 NVMe on Linux.md"};function m(x,n,g,v,f,N){const t=o("Link");return r(),p("div",null,[n[21]||(n[21]=u(`<h1 id="linux-上的-nvme" tabindex="-1">Linux 上的 NVMe <a class="header-anchor" href="#linux-上的-nvme" aria-label="Permalink to Linux 上的 NVMe">​</a></h1><blockquote><p>如果你还没注意到，一些极速的固态磁盘技术已经可以用在 Linux 和其他操作系统上了。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/05/nvme-100797708-large.jpg" alt="Sandra Henry-Stocker"></p><p>NVMe 意即<ruby>非易失性内存主机控制器接口规范<rt>non-volatile memory express</rt></ruby>，它是一个主机控制器接口和存储协议，用于加速企业和客户端系统以及固态驱动器（SSD）之间的数据传输。它通过电脑的高速 PCIe 总线工作。每当我看到这些名词时，我的感受是“羡慕”。而羡慕的原因很重要。</p><p>使用 NVMe，数据传输的速度比旋转磁盘快很多。事实上，NVMe 驱动能够比 SATA SSD 快 7 倍。这比我们今天很多人用的固态硬盘快了 7 倍多。这意味着，如果你用一个 NVMe 驱动盘作为启动盘，你的系统能够启动的非常快。事实上，如今任何人买一个新的系统可能都不会考虑那些没有自带 NVMe 的，不管是服务器或者个人电脑。</p><h3 id="nvme-在-linux-下能工作吗" tabindex="-1">NVMe 在 Linux 下能工作吗？ <a class="header-anchor" href="#nvme-在-linux-下能工作吗" aria-label="Permalink to NVMe 在 Linux 下能工作吗？">​</a></h3><p>是的！NVMe 自 Linux 内核 3.3 版本就支持了。然而，要升级系统，通常同时需要一个 NVMe 控制器和一个 NVMe 磁盘。一些外置磁盘也行，但是要连接到系统上，需要的可不仅仅是通用的 USB 接口。</p><p>先使用下列命令检查内核版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ uname -r</span></span>
<span class="line"><span>5.0.0-15-generic</span></span></code></pre></div><p>如果你的系统已经用了 NVMe，你将看到一个设备（例如，<code>/dev/nvme0</code>），但是只有在你安装了 NVMe 控制器的情况下才显示。如果你没有 NVMe 控制器，你可以用下列命令获取使用 NVMe 的相关信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ modinfo nvme | head -6</span></span>
<span class="line"><span>filename:       /lib/modules/5.0.0-15-generic/kernel/drivers/nvme/host/nvme.ko</span></span>
<span class="line"><span>version:        1.0</span></span>
<span class="line"><span>license:        GPL</span></span>
<span class="line"><span>author:         Matthew Wilcox &lt;willy@linux.intel.com&gt;</span></span>
<span class="line"><span>srcversion:     AA383008D5D5895C2E60523</span></span>
<span class="line"><span>alias:          pci:v0000106Bd00002003sv*sd*bc*sc*i*</span></span></code></pre></div><h3 id="了解更多" tabindex="-1">了解更多 <a class="header-anchor" href="#了解更多" aria-label="Permalink to 了解更多">​</a></h3>`,12)),l("p",null,[n[1]||(n[1]=e("如果你想了解极速的 NVMe 存储的更多细节，可在 ")),s(t,{href:"https://www.pcworld.com/article/2899351/everything-you-need-to-know-about-nvme.html"},{default:a(()=>n[0]||(n[0]=[e("PCWorld")])),_:1}),n[2]||(n[2]=e(" 获取。"))]),l("p",null,[n[4]||(n[4]=e("规范、白皮书和其他资源可在 ")),s(t,{href:"https://nvmexpress.org/"},{default:a(()=>n[3]||(n[3]=[e("NVMexpress.org")])),_:1}),n[5]||(n[5]=e(" 获取。"))]),n[22]||(n[22]=l("hr",null,null,-1)),l("p",null,[n[7]||(n[7]=e("via: ")),s(t,{href:"https://www.networkworld.com/article/3397006/nvme-on-linux.html"},{default:a(()=>n[6]||(n[6]=[e("https://www.networkworld.com/article/3397006/nvme-on-linux.html")])),_:1})]),l("p",null,[n[12]||(n[12]=e("作者：")),s(t,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:a(()=>n[8]||(n[8]=[e("Sandra Henry-Stocker")])),_:1}),n[13]||(n[13]=e(" 选题：")),s(t,{href:"https://github.com/lujun9972"},{default:a(()=>n[9]||(n[9]=[e("lujun9972")])),_:1}),n[14]||(n[14]=e(" 译者：")),s(t,{href:"https://github.com/warmfrog"},{default:a(()=>n[10]||(n[10]=[e("warmfrog")])),_:1}),n[15]||(n[15]=e(" 校对：")),s(t,{href:"https://github.com/wxy"},{default:a(()=>n[11]||(n[11]=[e("wxy")])),_:1})]),l("p",null,[n[18]||(n[18]=e("本文由 ")),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>n[16]||(n[16]=[e("LCTT")])),_:1}),n[19]||(n[19]=e(" 原创编译，")),s(t,{href:"https://linux.cn/"},{default:a(()=>n[17]||(n[17]=[e("Linux中国")])),_:1}),n[20]||(n[20]=e(" 荣誉推出"))])])}const w=i(d,[["render",m]]);export{b as __pageData,w as default};
